#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, sys

if len(sys.argv) != 2: raise SystemExit('usage: 0141-domain-admin.py <source-root>')
root = Path(sys.argv[1]).resolve()

p = root / 'gradle.properties'
s = p.read_text()
if 'mod_version=0.1.40-dev' not in s: raise SystemExit('Expected 0.1.40 version marker not found')
p.write_text(s.replace('mod_version=0.1.40-dev', 'mod_version=0.1.41-dev', 1))

p = root / 'src/main/java/dev/futurae/veilbound/domain/DomainState.java'
s = p.read_text()
old = '    public boolean completeMilestone(String milestoneId) {\n        String id = Objects.requireNonNull(milestoneId, "milestoneId");\n        if (id.isBlank()) throw new IllegalArgumentException("milestoneId may not be blank");\n        boolean added = completedMilestoneIds.add(id);\n        if (added) changed();\n        return added;\n    }\n'
new = '    public boolean completeMilestone(String milestoneId) {\n        String id = Objects.requireNonNull(milestoneId, "milestoneId");\n        if (id.isBlank()) throw new IllegalArgumentException("milestoneId may not be blank");\n        boolean added = completedMilestoneIds.add(id);\n        if (added) changed();\n        return added;\n    }\n    public boolean revokeMilestone(String milestoneId) {\n        String id = Objects.requireNonNull(milestoneId, "milestoneId");\n        if (id.isBlank()) throw new IllegalArgumentException("milestoneId may not be blank");\n        boolean removed = completedMilestoneIds.remove(id);\n        if (removed) changed();\n        return removed;\n    }\n'
if old not in s: raise SystemExit('Expected milestone completion method not found')
p.write_text(s.replace(old, new, 1))

p = root / 'src/main/java/dev/futurae/veilbound/matter/MatterTransmutationState.java'
s = p.read_text()
marker = '    public long addMatter(long amount) {\n'
insert = '    public void setStoredMatter(long amount) {\n        if (amount < 0) throw new IllegalArgumentException("amount must be >= 0");\n        if (storedMatter != amount) {\n            storedMatter = amount;\n            changed();\n        }\n    }\n\n    public boolean forget(String itemId) {\n        String normalized = normalize(itemId);\n        boolean changed = learnedItemIds.remove(normalized);\n        if (favoriteItemIds.remove(normalized)) changed = true;\n        if (recentItemIds.remove(normalized)) changed = true;\n        if (changed) changed();\n        return changed;\n    }\n\n'
if marker not in s: raise SystemExit('Expected addMatter marker not found')
p.write_text(s.replace(marker, insert + marker, 1))

encoded = ''
p = root / 'src/main/java/dev/futurae/veilbound/platform/neoforge/NeoForgeDomainAdminCommandCoordinator.java'
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(gzip.decompress(base64.b64decode(encoded)))

p = root / 'src/main/java/dev/futurae/veilbound/Veilbound.java'
s = p.read_text()
if 'NeoForgeDomainAdminCommandCoordinator' not in s:
    s = s.replace('import dev.futurae.veilbound.platform.neoforge.NeoForgeDefinitionReloadCoordinator;\n', 'import dev.futurae.veilbound.platform.neoforge.NeoForgeDefinitionReloadCoordinator;\nimport dev.futurae.veilbound.platform.neoforge.NeoForgeDomainAdminCommandCoordinator;\n', 1)
    s = s.replace('    private static final NeoForgeMatterCommandCoordinator MATTER_COMMANDS =\n            new NeoForgeMatterCommandCoordinator(RUNTIME);\n', '    private static final NeoForgeMatterCommandCoordinator MATTER_COMMANDS =\n            new NeoForgeMatterCommandCoordinator(RUNTIME);\n    private static final NeoForgeDomainAdminCommandCoordinator DOMAIN_ADMIN_COMMANDS =\n            new NeoForgeDomainAdminCommandCoordinator(RUNTIME);\n', 1)
    s = s.replace('        NeoForge.EVENT_BUS.addListener(MATTER_COMMANDS::onRegisterCommands);\n', '        NeoForge.EVENT_BUS.addListener(MATTER_COMMANDS::onRegisterCommands);\n        NeoForge.EVENT_BUS.addListener(DOMAIN_ADMIN_COMMANDS::onRegisterCommands);\n', 1)
p.write_text(s)

print('Applied 0.1.41 offline/UUID Domain administration and registry-backed suggestions')